import{_ as e,o,c as r,a2 as a}from"./chunks/framework.B_GyVC5q.js";const m=JSON.parse('{"title":"Selection tools","description":"","frontmatter":{"title":"Selection tools"},"headers":[],"relativePath":"guide/selection-tools.md","filePath":"guide/selection-tools.md"}'),n={name:"guide/selection-tools.md"};function s(i,t,l,d,c,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="selection-tools" tabindex="-1">Selection tools <a class="header-anchor" href="#selection-tools" aria-label="Permalink to &quot;Selection tools&quot;">​</a></h1><p>Wherever you have an <strong>entity set</strong> (Entity list after a query, Method Executor selection result, related selection, Home entity-set row, or tab context menu), open <strong>Selection tools</strong> to analyze, export, import, or anonymize that selection. <a href="/4d-dataexplorer/guide/parts.html#dataclass-browser">Named parts</a>.</p><p>Entry points include:</p><ul><li>Dataclass list toolbar (<strong>⋯</strong> / Selection tools)</li><li>Dataclass tab context menu</li><li>Method Executor entity-selection result</li><li>Related entity-set actions</li><li>Home screen entity-set rows</li><li>Command palette (<strong>Analyze</strong>, <strong>Export</strong>, <strong>Import</strong>, <strong>Anonymize</strong>)</li></ul><p>An entity set is required for analyze, export, and anonymize. <strong>Import</strong> always targets the currently open dataclass and does not require a selection.</p><h2 id="analyze" tabindex="-1">Analyze <a class="header-anchor" href="#analyze" aria-label="Permalink to &quot;Analyze&quot;">​</a></h2><p><strong>Analyze</strong> inspects one attribute on the current entity set:</p><ul><li><strong>Distinct values</strong> — uses 4D REST <code>$distinct</code> on the attribute path</li><li><strong>Compute</strong> — min / max / average / count via <code>$compute=$all</code> when the type supports it</li></ul><p>Pick an attribute, then refresh to reload stats.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p><strong>Export</strong> downloads the current selection (or filter / whole dataclass when no set is bound) in an extendable format registry:</p><table tabindex="0"><thead><tr><th>Format</th><th>Typical use</th></tr></thead><tbody><tr><td>JSON / JSON REST / JSON Lines</td><td>Interchange and tooling</td></tr><tr><td>CSV / TSV</td><td>Spreadsheets</td></tr><tr><td>SQL</td><td><code>INSERT</code> scripts</td></tr><tr><td>XML / YAML / Markdown / HTML</td><td>Docs and structured dumps</td></tr></tbody></table><p>Choose columns (select all / none), then download. Large selections ask for confirmation before paging through the entity set.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p><strong>Import</strong> reads a file (or pasted content), detects the format when possible, previews rows, and writes into the <strong>current dataclass</strong>:</p><ul><li><strong>Create</strong> — new records (<code>$method=update</code> batch create)</li><li><strong>Update</strong> — existing records; each row must include <code>__KEY</code> and <code>__STAMP</code></li></ul><p>Supported parsers match the export registry where implemented (JSON family, CSV/TSV, SQL inserts, XML, …).</p><h2 id="anonymize" tabindex="-1">Anonymize <a class="header-anchor" href="#anonymize" aria-label="Permalink to &quot;Anonymize&quot;">​</a></h2><p><strong>Anonymize</strong> replaces mapped fields with synthetic data (or fixed values) using the same template engine as <a href="./browsing.html#create-entity">Create entity</a> and <a href="./environments.html">Environment variables</a>:</p><ul><li><strong>Field mapping</strong> — add, change, or remove rows; per attribute: <strong>Faker</strong> (<code>{{$faker… | filters}}</code>), <strong>Fixed value</strong>, <strong>Keep</strong>, or <strong>Empty</strong>. <strong>Restore defaults</strong> rebuilds the plan from the dataclass schema</li><li><strong>Remove fields</strong> — drop a row from the mapping so that attribute is <strong>not</strong> included in download, import-as-new, or in-place update payloads</li><li><strong>Pick lists</strong> — declare named value pools under <a href="./environments.html#pick-lists-this-database">Environments → This database</a> (dataclass + attribute). Anonymize loads <code>$distinct</code> values on demand when a Faker template references <code>{{$pick | from:$lists.&lt;name&gt;}}</code> (also <code>$sample</code> / <code>$unique</code>)</li><li><strong>Seed</strong> — optional Faker seed for reproducible dumps</li><li><strong>Preview</strong> — same multi-mode viewer as the HTTP Client (Code / HTML / Markdown / JSON / CSV), with auto-detected default from the chosen export format</li></ul><p>Actions:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Download</strong></td><td>Export anonymized rows (create-shaped payload, no PK / system keys)</td></tr><tr><td><strong>Import as new</strong></td><td>Create new records from the anonymized mapping</td></tr><tr><td><strong>Anonymize existing</strong></td><td>Overwrite mapped fields on the <strong>current entity set</strong> (confirmation required; sends <code>__KEY</code> / <code>__STAMP</code> plus changed fields only)</td></tr></tbody></table><p>Templates support pipe filters (for example <code>{{$faker.internet.username | lower}}</code>) and autocomplete, consistent with create-entity templating.</p><p>Writable <strong>Image</strong> attributes also accept <a href="/4d-dataexplorer/guide/trusted-folders.html">trusted folder</a> templates such as <code>{{$files.photos}}</code> (desktop/mobile). The run loads the local file and uploads it through <code>$upload</code> instead of fetching a remote Faker image URL.</p>',24)])])}const g=e(n,[["render",s]]);export{m as __pageData,g as default};
